import json
from fractions import Fraction

# Train length L, speed v = L/t. Passing the pole takes t seconds.
# Passing the platform of length P takes 6t seconds: (L + P) / v = 6t  =>  L + P = 6L  =>  P = 5L.
# The platform is given as 5l, where l is the train's length. So L = P/5 = l.

evidence = []
ok = True
for l in [Fraction(1), Fraction(7, 3), Fraction(120), Fraction(1, 2)]:
    for t in [Fraction(1), Fraction(5, 2), Fraction(9)]:
        P = 5 * l                  # platform length from the givens
        L = P / 5                  # from L + P = 6L  => L = P/5
        v = L / t
        time_platform = (L + P) / v
        if time_platform != 6 * t or L != l:
            ok = False
        evidence.append({"l": str(l), "t": str(t), "L": str(L), "platform_time": str(time_platform)})

if ok:
    result = {
        "final_answer": "l (the train's length equals l; platform = 5 times train length)",
        "evidence": {
            "derivation": "L + P = 6L => P = 5L; with P = 5l, L = l",
            "checks_passed": len(evidence),
            "samples": evidence[:3],
        },
    }
    print(json.dumps(result))
else:
    print("UNSUPPORTED")
```

