import json
from collections import defaultdict

facts = """Bernhard is a frog.
Lily is a frog.
Lily is gray.
Brian is a lion.
Greg is a swan.
Julius is a swan.
Greg is gray.
Brian is white.
Julius is gray."""

colors = {"gray", "white", "red", "green", "blue", "yellow", "black", "brown"}
species = {}
color = {}
for line in facts.splitlines():
    w = line.rstrip(".").split()
    name = w[0]
    if w[2] in ("a", "an"):
        species[name] = w[3]
    else:
        color[name] = w[2]

target = "Bernhard"

# Evidence: colors of known members of each species
by_species = defaultdict(dict)
for n, s in species.items():
    if n in color:
        by_species[s][n] = color[n]

# Check that species determines color in all observed data (no contradictions)
consistent = all(len(set(m.values())) == 1 for m in by_species.values())

if target in color:
    answer = color[target]
    basis = "stated directly"
elif consistent and species.get(target) in by_species:
    cs = set(by_species[species[target]].values())
    answer = cs.pop()
    basis = "species-color regularity consistent in all observed data"
else:
    answer = "UNSUPPORTED"
    basis = "no determining evidence"

if answer == "UNSUPPORTED":
    print("UNSUPPORTED")
else:
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "target_species": species.get(target),
            "same_species_known_colors": by_species.get(species.get(target), {}),
            "species_color_consistent": consistent,
            "basis": basis,
        }
    }))
