import json, itertools

def mul(a, b):
    return (a[0]*b[0]-a[1]*b[1], a[0]*b[1]+a[1]*b[0])
def add(a, b):
    return (a[0]+b[0], a[1]+b[1])
def sub(a, b):
    return (a[0]-b[0], a[1]-b[1])

def coeffs_from_roots(roots):
    # coefficients low->high, monic, built by Vieta-style expansion
    c = [(1, 0)]
    for r in roots:
        new = [(0, 0)] * (len(c) + 1)
        for i, ci in enumerate(c):
            new[i+1] = add(new[i+1], ci)                 # z * term
            new[i] = sub(new[i], mul(r, ci))             # -r * term
        c = new
    return c

def horner(c, z):
    acc = (0, 0)
    for ci in reversed(c):
        acc = add(mul(acc, z), ci)
    return acc

def prod_form(roots, z):
    acc = (1, 0)
    for r in roots:
        acc = mul(acc, sub(z, r))
    return acc

pts = [(x, y) for x in range(-3, 4) for y in range(-3, 4)]
vals = [(a, b) for a in range(-2, 3) for b in range(-1, 2)]
bset = set()
count = 0
for n in range(1, 5):
    for roots in itertools.islice(itertools.product(vals, repeat=n), 0, 400):
        c = coeffs_from_roots(roots)
        assert c[-1] == (1, 0)
        for z in pts:
            # b = prod(z - z_i) - p(z) must be the same constant for all z
            bset.add(sub(prod_form(roots, z), horner(c, z)))
        count += 1

